// email is "HC-Not Online" whenever one of its intents is. email_intent is a comma string on a
// multi-intent case, matches no key, and the lookup below falls back to the default topic.
const NOT_ONLINE_TOPIC = "HC-Not Online";
let hasNotOnlineIntent = detectedIntents.some(key =>
  salesforceByIntent[key] && salesforceByIntent[key].topic === NOT_ONLINE_TOPIC);
let matchedIntent = salesforceByIntent[email_intent] || { topic: "HC-Online", subtopic: "" };
